package app.gendragoon.cloudssd.mobile;
import android.app.Activity;
import android.content.*;
import android.net.Uri;
import android.os.Bundle;
import android.webkit.*;
import android.widget.TextView;
import androidx.webkit.*;
import java.util.*;
import java.util.concurrent.*;
import org.json.*;

/** Isolated packaged Teams page. Its bridge never exposes file operations. */
public final class TeamsActivity extends Activity {
    private WebView web;private final ExecutorService io=Executors.newFixedThreadPool(2);private String subject,workspace,name;private final Set<String> pending=java.util.concurrent.ConcurrentHashMap.newKeySet();
    static void open(Context context,String subject,String workspace,String name){context.startActivity(new Intent(context,TeamsActivity.class).putExtra("subject",subject).putExtra("workspace",workspace).putExtra("name",name));}
    @Override public void onCreate(Bundle saved){super.onCreate(saved);subject=getIntent().getStringExtra("subject");workspace=getIntent().getStringExtra("workspace");name=getIntent().getStringExtra("name");if(subject==null||!WebViewFeature.isFeatureSupported(WebViewFeature.WEB_MESSAGE_LISTENER)){TextView message=new TextView(this);message.setText("Update Android System WebView to use the private developer Teams interface.");setContentView(message);return;}web=new WebView(this);setContentView(web);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setDomStorageEnabled(false);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);WebViewAssetLoader loader=new WebViewAssetLoader.Builder().addPathHandler("/assets/",new WebViewAssetLoader.AssetsPathHandler(this)).build();web.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){WebResourceResponse response=loader.shouldInterceptRequest(request.getUrl());return response!=null?response:new WebResourceResponse("text/plain","UTF-8",403,"Blocked",java.util.Collections.emptyMap(),new java.io.ByteArrayInputStream(new byte[0]));}@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){return !"https://appassets.androidplatform.net/assets/teams/index.html".equals(request.getUrl().toString());}});
        WebViewCompat.addWebMessageListener(web,"gdAndroid",Set.of("https://appassets.androidplatform.net"),(view,message,origin,mainFrame,reply)->{if(!mainFrame||!"https".equals(origin.getScheme())||!"appassets.androidplatform.net".equals(origin.getHost())||origin.getPort()!=-1||message.getData()==null||message.getData().length()>16384)return;try{JSONObject value=new JSONObject(message.getData());if("ready".equals(value.optString("kind"))){reply.postMessage(new JSONObject().put("kind","configure").put("config",new JSONObject().put("workspaceId",workspace==null?"":workspace).put("workspaceName",name==null?"":name)).toString());return;}String id=value.getString("id"),path=value.getString("path"),method=value.optString("method","GET");if(!id.matches("[a-f0-9]{32}")||!allowed(path,method)||pending.size()>=32||!pending.add(id))return;io.execute(()->{try{JSONObject current=RedXSession.profile(this);if(current==null||!subject.equals(current.optString("subject")))throw new java.io.IOException("Your account changed. Reopen Teams.");JSONObject response=new CloudApi(this,subject).request(path,method,value.optJSONObject("body")).json();runOnUiThread(()->send(reply,id,response,null));}catch(Exception error){runOnUiThread(()->send(reply,id,null,"The team request failed. Check membership and your Red-XAI connection."));}finally{pending.remove(id);}});}catch(Exception ignored){/* Invalid web packets cannot invoke native storage. */}});
        web.loadUrl("https://appassets.androidplatform.net/assets/teams/index.html");}
    static boolean allowed(String path,String method){if(path==null||path.length()>4096||path.contains("..")||path.contains("\\")||path.contains("#")||path.contains("\r")||path.contains("\n")||!Set.of("GET","POST","PUT","PATCH","DELETE").contains(method))return false;String base=path.split("\\?",2)[0];if(base.contains("%"))return false;return base.matches("/v1/receivers/(me/dev-(profile|teams|community)|me/dev-reports(/[a-f0-9]{32})?|me/workspaces/[a-f0-9]{32}/team|teams/(join|[a-f0-9]{32}(/(members|invites|messages|presence|signals|membership|blocks|reports)(/[a-f0-9]{32})?)?))");}
    private void send(JavaScriptReplyProxy reply,String id,JSONObject result,String error){if(isFinishing()||isDestroyed())return;try{JSONObject value=new JSONObject().put("id",id).put("ok",error==null);if(error==null)value.put("result",result);else value.put("error",new JSONObject().put("message",error));reply.postMessage(value.toString());}catch(Exception ignored){}}
    @Override protected void onDestroy(){io.shutdownNow();if(web!=null){web.stopLoading();web.destroy();web=null;}super.onDestroy();}
}
